using System;using System.IO;using System.Net;using System.Text;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;using System.Web.Script.Serialization;
internal static class PluginCatalog {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=32*1024*1024,RecursionLimit=24};
 static Dictionary<string,object> Obj(params object[] p){var o=new Dictionary<string,object>();for(int i=0;i<p.Length;i+=2)o[(string)p[i]]=p[i+1];return o;}
 static string S(Dictionary<string,object> o,string k){object v;return o.TryGetValue(k,out v)&&v is string?(string)v:"";}
 static byte[] Fetch(Uri uri,int limit){for(int hop=0;hop<6;hop++){if(uri.Scheme!="https")throw new Exception("只支持 HTTPS 插件源");var r=(HttpWebRequest)WebRequest.Create(uri);r.UserAgent="Hhub-Plugin-Catalog/1.0";r.Timeout=12000;r.ReadWriteTimeout=12000;r.AllowAutoRedirect=false;using(var response=(HttpWebResponse)r.GetResponse()){if((int)response.StatusCode>=300&&(int)response.StatusCode<400){uri=new Uri(uri,response.Headers["Location"]);continue;}if(response.ContentLength>limit)throw new Exception("插件源内容过大");using(var stream=response.GetResponseStream())using(var data=new MemoryStream()){byte[] b=new byte[8192];int n;while((n=stream.Read(b,0,b.Length))>0){if(data.Length+n>limit)throw new Exception("插件源内容过大");data.Write(b,0,n);}return data.ToArray();}}}throw new Exception("插件源重定向过多");}
 static Dictionary<string,object> Parse(byte[] bytes){var o=Json.DeserializeObject(Encoding.UTF8.GetString(bytes)) as Dictionary<string,object>;if(o==null)throw new Exception("插件清单格式无效");return o;}
 static string Digest(byte[] b){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(b)).Replace("-","").ToLowerInvariant();}
 static Dictionary<string,object> Validate(Dictionary<string,object> input,Dictionary<string,object> feed){Uri source;if(!Uri.TryCreate(S(input,"indexUrl"),UriKind.Absolute,out source)||source.Scheme!="https"||source.Host!="raw.githubusercontent.com")throw new Exception("请绑定 GitHub 原始插件清单地址");object schema,items;if(!feed.TryGetValue("schemaVersion",out schema)||Convert.ToInt32(schema)!=1||!feed.TryGetValue("plugins",out items)||!(items is object[]))throw new Exception("插件清单格式或版本不支持");var list=new List<object>();var ids=new HashSet<string>();foreach(object value in (object[])items){var e=value as Dictionary<string,object>;if(e==null||list.Count>=256)throw new Exception("插件清单条目无效");string id=S(e,"id"),hash=S(e,"sha256");Version version;Uri package;if(id.Length==0||id.Length>80||!ids.Add(id)||S(e,"name").Length==0||S(e,"author").Length==0||!Version.TryParse(S(e,"version"),out version)||hash.Length!=64||hash.Any(c=>!Uri.IsHexDigit(c))||!Uri.TryCreate(source,S(e,"packageUrl"),out package)||package.Scheme!="https"||package.Host!=source.Host||!package.AbsolutePath.StartsWith(new Uri(source,".").AbsolutePath,StringComparison.Ordinal))throw new Exception("插件条目身份、版本、摘要或地址无效");var entry=Obj("id",id,"name",S(e,"name"),"author",S(e,"author"),"version",S(e,"version"),"description",S(e,"description"),"kind",S(e,"kind"),"packageUrl",package.AbsoluteUri,"sha256",hash.ToLowerInvariant());object tags;if(e.TryGetValue("tags",out tags)&&tags is object[])entry["tags"]=tags;PluginContract.Validate(e,feed);foreach(var key in new[]{"compatibility","identityCode","verificationStatus","mobileUiVerified"})if(e.ContainsKey(key))entry[key]=e[key];list.Add(entry);}return Obj("ok",true,"name",S(feed,"name"),"plugins",list.ToArray(),"indexUrl",source.AbsoluteUri,"checkedAt",DateTime.UtcNow.ToString("o"));}
 static Dictionary<string,object> Sync(Dictionary<string,object> input){return Validate(input,Parse(Fetch(new Uri(S(input,"indexUrl")),262144)));}
 static Dictionary<string,object> Download(Dictionary<string,object> input){var entry=(Dictionary<string,object>)input["entry"];Uri uri;if(!Uri.TryCreate(S(entry,"packageUrl"),UriKind.Absolute,out uri)||uri.Scheme!="https"||uri.Host!="raw.githubusercontent.com")throw new Exception("插件下载地址无效");return Verify(entry,Fetch(uri,8*1024*1024));}
 static Dictionary<string,object> Verify(Dictionary<string,object> entry,byte[] bytes){if(bytes.Length>8*1024*1024)throw new Exception("插件包不能超过 8 MB");if(Digest(bytes)!=S(entry,"sha256").ToLowerInvariant())throw new Exception("插件包 SHA-256 校验失败");var manifest=Parse(bytes);if(S(manifest,"id")!=S(entry,"id")||S(manifest,"author")!=S(entry,"author")||S(manifest,"version")!=S(entry,"version"))throw new Exception("插件包身份与清单不匹配");PluginContract.VerifyManifest(entry,manifest);return Obj("ok",true,"manifest",manifest,"sha256",Digest(bytes));}
 public static int Main(string[] args){if(args.Length!=3)return 2;ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;Dictionary<string,object> result;try{var input=Parse(File.ReadAllBytes(args[1]));if(args[0]=="--sync")result=Sync(input);else if(args[0]=="--download")result=Download(input);else if(args[0]=="--validate")result=Validate(input,(Dictionary<string,object>)input["catalog"]);else if(args[0]=="--match"){var feed=Validate(input,(Dictionary<string,object>)input["catalog"]);var device=(Dictionary<string,object>)input["device"];result=Obj("ok",true,"plugins",((object[])feed["plugins"]).Where(x=>PluginContract.Matches((Dictionary<string,object>)x,device)).ToArray());}else if(args[0]=="--verify-local")result=Verify((Dictionary<string,object>)input["entry"],File.ReadAllBytes(S(input,"packageFile")));else throw new Exception("未知插件库操作");}catch(Exception e){result=Obj("ok",false,"error",e.Message);}File.WriteAllText(args[2],Json.Serialize(result),new UTF8Encoding(false));return (bool)result["ok"]?0:1;}
}
